def test_the_routines_held_with_no_table_entry_have_none_and_the_unbound_pin_holds_them(monkeypatch):
    """LINKED_HELD_NO_TABLE_ENTRY's routines are NO TARGET OF THE ROM'S TABLE (else LINKED_AND_NOT_FLIPPED is their
    list) and in no other list; and THE DESK'S ONE UNBOUND PIN HOLDS THEM: a name put in the set puts its core in
    `aes_deskbind.held_cores()` — the closure every unit's pin grows from — as one of LINKED_AND_NOT_FLIPPED's is."""
    held_alone = linef_table.LINKED_HELD_NO_TABLE_ENTRY
    targets = set(linef_table.rom_table())
    assert not {name for name in held_alone if getattr(addrs, name) in targets}, "a routine of the set has a table entry"
    assert not set(held_alone) & set(linef_table.LINKED_AND_NOT_FLIPPED)
    assert getattr(addrs, NO_TABLE_ENTRY_PROBE) not in targets
    probe_core = routines.core_symbol(NO_TABLE_ENTRY_PROBE)
    monkeypatch.setitem(held_alone, NO_TABLE_ENTRY_PROBE, "the probe")
    assert probe_core in aes_deskbind.held_cores()
    assert probe_core in aes_deskbind.unbound_closure({probe_core: set()})


# ---- band 6 slice B0: THE TWO DIVERGENCES THE BINDING EXPOSES, DECLARED (rulings R2 and R9, the user's) --------------------
# R2 — THE D0 A VOID ROUTINE OF OURS LEAVES A ROM CALLER: a C core of no answer leaves D0 as its code left it, where the
# ROM's routine left a word (its last store's). DECLARED, not reproduced, and PINNED BY READING THE CALLERS
# (`aes_deskbind.answer_readers`: every call site of the ROM's GEM text, both arms of every branch, through the callers
# that return it as their own): every instruction that reads it lies in THE AES's OWN TEXT — outside the desk's ranges
# (`aes_desk.DESK_TEXT`, `UTILITY_TEXT`), which no run of ours executes behind the door — or in A DESK BINDING whose own
# answer no instruction of the ROM reads (`test_desk_bind.READ_AT`, unit D's battery). EACH READER INSIDE THE BINDING
# IT IS ATTRIBUTED TO (the fix pass, reviewer A's F5): between the binding's entry and the next routine start the AES
# map's inventory lists (`aes_desk.inventoried`) — a desk-text reader in no binding is refused by name, not given to the
# binding below it.
def _the_binding_holding(at):
    """The desk binding whose body holds the instruction `at` — from its entry to the next routine start the AES map's
    inventory lists — or None where `at` lies in no binding's."""
    import bisect
    import aes_desk
    entries = sorted((aes_deskbind.entry_of(short), short) for short in aes_deskbind.SIGNATURES)
    below = [each for each in entries if each[0] <= at]
    starts = aes_desk.inventoried()
    return below[-1][1] if below and starts[bisect.bisect_right(starts, at) - 1] == below[-1][0] else None


def test_a_reader_is_given_to_the_binding_whose_body_holds_it_and_to_no_other():
    """`_the_binding_holding` read by hand: the last binding's entry and its last word are its own; the routine the
    inventory lists after it, and deskmain, are no binding's."""
    import aes_desk
    last_entry, last = max((aes_deskbind.entry_of(short), short) for short in aes_deskbind.SIGNATURES)
    after = next(start for start in aes_desk.inventoried() if start > last_entry)
    assert _the_binding_holding(last_entry) == last == _the_binding_holding(after - WORD_BYTES)
    assert _the_binding_holding(after) is None and _the_binding_holding(addrs.AES_ROM_DESKMAIN) is None


def test_the_d0_a_void_routine_of_ours_leaves_a_rom_caller_is_read_by_no_rom_instruction_that_runs_on_our_shore():
    import aes_desk
    import test_desk_bind
    desk_ranges = (aes_desk.DESK_TEXT, aes_desk.UTILITY_TEXT)
    void = sorted(name for name in (*THUNKED, *linef_table.LINKED_AND_NOT_FLIPPED) if vdi.ALCYON[name].restype is None)
    exposed, outside = {}, []
    for name in void:
        for at in aes_deskbind.answer_readers(getattr(addrs, name)):
            if not any(lo <= at < hi for lo, hi in desk_ranges):
                continue                # ...the AES's own text: ours behind the door, never run
            binding = _the_binding_holding(at)
            if binding is None:
                outside.append(f"${at:x}")
            elif binding in test_desk_bind.READ_AT:
                exposed.setdefault(name, []).append(f"${at:x} ({binding})")
    assert not outside, f"a desk-text reader of a void routine's D0 lies in no binding: {outside}"
    assert len(void) > 100 and not exposed, f"a ROM instruction our shore runs reads a void routine's D0: {exposed}"


# R9 — app_blddesk's AES_XBIOS_RETURN on the shipped blob: a C caller of the XBIOS door's thunk parks the thunk's own
# return there, where the ROM's door parks its caller's. DECLARED, and PINNED: the only instructions of the ROM that name
# the longword are trp14's own two — its park and, after its trap, its read of what it parked — so nothing reads what a
# call left there once the call has returned. WHAT THE SCAN READS (the fix pass, reviewer A's F6): every ABSOLUTE-LONG
# operand of the ROM's GEM text (`AES_TEXT`) that holds the address — the one form of the ROM's to name a global of
# THEGLO. Absolute-short cannot reach it (a word operand is sign-extended: `$95b2` names `$ff95b2`); a register-based
# access (`d16(An)`, an index) is NOT scanned — its base is a run's value, not an operand's — and is recorded so,
# unpinned by name.
XBIOS_DOOR_PARKS_AT, XBIOS_DOOR_READS_BACK_AT = 0xFEE488, 0xFEE490
MOVE_L_POP_TO_ABSOLUTE, MOVE_L_ABSOLUTE_PUSH, TRAP_14 = 0x23DF, 0x2F39, 0x4E4E


def test_the_xbios_door_s_parked_return_is_named_by_trp14_alone():
    named = [at - WORD_BYTES for at in range(0, len(BASE_IMAGE) - LONG_BYTES + 1, WORD_BYTES)
             if case.long_in(BASE_IMAGE, at) == aes.AES_XBIOS_RETURN and aes.AES_TEXT[0] <= at < aes.AES_TEXT[1]]
    assert named == [XBIOS_DOOR_PARKS_AT, XBIOS_DOOR_READS_BACK_AT]
    assert [case.word_in(BASE_IMAGE, at) for at in named] == [MOVE_L_POP_TO_ABSOLUTE, MOVE_L_ABSOLUTE_PUSH]
    # ...both trp14's own: its first instruction, and the one after its trap
    assert XBIOS_DOOR_PARKS_AT == addrs.AES_ROM_TRP14 and case.word_in(BASE_IMAGE, XBIOS_DOOR_READS_BACK_AT - WORD_BYTES) == TRAP_14
